class WrappedInputStream extends InputStream {
    private InputStream inputStream;
    private long remaining;
    private long size;
    private static final int DEFAULT_BUFFER_SIZE = 1024;
    private byte[] buffer;

    public WrappedInputStream(InputStream inputStream) {
        this.inputStream = inputStream;
        this.remaining = -1;
        this.size = 0;
        this.buffer = new byte[DEFAULT_BUFFER_SIZE];
    }

    @Override
    public int read() throws IOException {
        if (remaining == 0) {
            throw new EOFException("Reached the end of the stream.");
        }

        int read = inputStream.read();
        remaining--;
        size++;

        if (read == -1) {
            throw new EOFException("Reached the end of the stream.");
        }

        return read;
    }

    @Override
    public int read(byte[] b) throws IOException {
        if (remaining == 0) {
            throw new EOFException("Reached the end of the stream.");
        }

        int read = inputStream.read(b);
        remaining -= read;
        size += read;

        if (read == -1) {
            throw new EOFException("Reached the end of the stream.");
        }

        return read;
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        if (remaining == 0) {
            throw new EOFException("Reached the end of the stream.");
        }

        int read = inputStream.read(b, off, len);
        remaining -= read;
        size += read;

        if (read == -1) {
            throw new EOFException("Reached the end of the stream.");
        }

        return read;
    }

    @Override
    public long skip(long n) throws IOException {
        if (n >= 0) {
            if (n > remaining) {
                n = remaining;
            }
            n = inputStream.skip(n);
            remaining -= n;
            size += n;

            if (n == 0) {
                throw new EOFException("Reached the end of the stream.");
            }
        }

        return n;
    }

    @Override
    public int available() throws IOException {
        return (int)Math.min(Integer.MAX_VALUE, remaining);
    }

    @Override
    public void close() throws IOException {
        inputStream.close();
    }

    @Override
    public synchronized void mark(int readlimit) {
        return inputStream.mark(readlimit);
    }

    @Override
    public synchronized void reset() throws IOException {
        return inputStream.reset();
    }

    @Override
    public boolean markSupported() {
        return inputStream.markSupported();
    }
}
