/**
 * findSmallestInteger: given a positive integer n, returns the smallest integer that can be formed by rearranging the digits of n
 * @param n - a positive integer
 * @return the smallest integer greater than n formed by rearranging the digits of n, or -1 if not possible
 */
public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    String numStr = Integer.toString(n);
    int numStrLength = numStr.length();
    int[] numArr = new int[numStrLength];
    for (int i = 0; i < numStrLength; i++) {
        numArr[i] = Character.digit(numStr.charAt(i), 10);
    }
    int smallestNum = Integer.valueOf(numStr);
    int currentNum = 0;
    // sort the digits in the input number
    Arrays.sort(numArr);
    do {
        // concatenate the sorted digits to form a new number
        currentNum = Integer.valueOf(convertArrayToString(numArr));
        if (currentNum > n) {
            // if the new number is greater than the input number, return the previous number
            return smallestNum;
        }
        smallestNum = currentNum;
    } while (nextPermutation(numArr));
    // if no permutation can form a number greater than the input number, return -1
    return -1;
}

/**
 * Converts an integer array representing a number to a String
 * @param numArr - an integer array representing a number
 * @return the String representation of the number
 */
private static String convertArrayToString(int[] numArr) {
    String numStr = "";
    for (int i = 0; i < numArr.length; i++) {
        numStr += String.valueOf(numArr[i]);
    }
    return numStr;
}

/**
 * Generates the next permutation of a given integer array in place
 * @param arr - an integer array
 * @return true if the next permutation exists, false otherwise
 */
private static boolean nextPermutation(int[] arr) {
    int i = arr.length - 1;
    while (i > 0 && arr[i] > arr[i - 1]) {
        i--;
    }
    if (i <= 0) return false;
    int j = arr.length - 1;
    while(arr[j] <= arr[i - 1]) {
        j--;
    }
    swap(arr, i - 1, j);
    rev(arr, i);
    return true;
}

/**
 * Swaps two elements in an integer array
 * @param arr - an integer array
 * @param i - the first index
 * @param j - the second index
 */
private static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

/**
 * Reverses an integer array given a starting index
 * @param arr - an integer array
 * @param i - the starting index
 */
private static void rev(int[] arr, int i) {
    int j = arr.length - 1;
    while (i < j) {
        swap(arr, i, j);
        i++;
        j--;
    }
}

